  Ltac tlx3_sc1 w io x3 EWB EW12v RD3 :=
    first
      [ eapply (sc_rd_w4s _ _ _ (wa_words w + 4 * io + 12) _ _);
          [ apply (adenot_of_estart _ _ (wa_words w + 4 * io + 12)); [unfold estart; cbn [a_base a_off]; rewrite EWB, u64_of_Z; lia | lia]
          | exact RD3 | ev_xs; reflexivity ]
      | eapply (sc_flat_lit asegs _ _ _ _ (wa_words w + 4 * io + 12) 4);
          [unfold estart; cbn [a_base a_off]; rewrite EWB, u64_of_Z; lia | apply elit_u; lia | lia | lia | lia]
      | eapply (sc_flat_lit asegs _ _ _ _ ((wa_words w + 4 * io + 12) / 8 + SHBASE) 1);
          [apply (estart_sh _ _ (wa_words w + 4 * io + 12) EW12v); lia | apply elit_u; lia
          | unfold SHBASE; Z.div_mod_to_equations; lia | lia | unfold SHBASE; Z.div_mod_to_equations; lia]
      | match goal with |- ?g => idtac "SCLEFT" g end ].

  Definition K3234 (w : pmwA H) (s : as_St H) LB LBs (m : mem) (c : pmc) F fc (Q : config -> Prop) : Prop :=
    forall msF1 mo1 m1 R1 (ty wd enc : Z),
      as_AKREL H s (mkCfg msF1 mo1) -> as_VIS H s msF1 = MS R1 F (Z_to_bv 64 0xf33c4) fc None m1 (seg_rom asegs) -> rfull R1 ->
      PMXA H LINV w s LB LBs m1 mo1 c S_INSTR TBL_EEF44 [] ->
      regs_tbl w R1 RT_3054 -> PropExec.getr R1 3%bv = wa_gp w -> PropExec.getr R1 4%bv = wa_tp w ->
      PropExec.getr R1 25%bv = Z_to_bv 64 ty -> 0 <= ty <= 3 ->
      PropExec.getr R1 23%bv = Z_to_bv 64 wd -> 0 <= wd < 2 ^ 64 ->
      PropExec.getr R1 19%bv = Z_to_bv 64 enc -> 0 <= enc < 2 ^ 64 ->
      ffkeepX w X3_FFX m m1 ->
      as_SR H Q (mkCfg msF1 mo1).

  Definition KB9C (w : pmwA H) (s : as_St H) LB LBs (m : mem) (c : pmc) F fc (Q : config -> Prop) : Prop :=
